//! AK-CALL-01: isolated, default-OFF call signaling contract.
//!
//! There is no socket, OS capture, recorder, File Gate grant, or device access.
//! PeerBinding and LocalPeerPolicy MUST come from independent authenticated
//! Iroh/QUIC identity and local consent. The wire is not a signature or grant.
//! Session IDs MUST be CSPRNG-generated by a future reviewed host. A durable
//! replay registry across restarts and live transport identity are NOT here.
//! A successful signaling "Accept" NEVER authorizes a microphone/camera/screen.

#![deny(clippy::all)]

use crate::p2p_offer_lab::PeerBinding;
use crate::sync::DeviceId;
use uuid::Uuid;

pub const VERSION: u8 = 1;
pub const MAX_RING_TTL_SECS: u64 = 120;
pub const WIRE_BYTES: usize = 147;
const MAGIC: &[u8; 8] = b"AKCALL01";
const OFF_CALL: usize = 11;
const OFF_SEQ: usize = 27;
const OFF_CREATED: usize = 35;
const OFF_EXPIRES: usize = 43;
const OFF_CALLER_DEVICE: usize = 51;
const OFF_CALLER_ENDPOINT: usize = 67;
const OFF_CALLEE_DEVICE: usize = 99;
const OFF_CALLEE_ENDPOINT: usize = 115;

pub type Wire = [u8; WIRE_BYTES];

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CallError {
    InvalidWire,
    UnsupportedVersion,
    Oversize,
    InvalidIdentity,
    InvalidLifetime,
    NotYetValid,
    Expired,
    WrongPeer,
    WrongCall,
    Replay,
    OutOfOrder,
    InvalidTransition,
    Denied,
    Revoked,
    Closed,
    SequenceExhausted,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LocalPeerPolicy {
    /// From local OS-backed permission store, not from an incoming message.
    Allowed,
    Unknown,
    Blocked,
    Revoked,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CallPhase {
    Dialing,
    RemoteRinging,
    IncomingRinging,
    Active,
    Closed,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RemoteEvent {
    Ringing,
    Accepted,
    Rejected,
    Busy,
    Cancelled,
    Ended,
    /// Display-only indication, NEVER a command to start local capture.
    RemoteMuted(bool),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Refusal {
    Reject,
    Busy,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Role {
    Caller,
    Callee,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Kind {
    Offer,
    Ringing,
    Accept,
    Reject,
    Busy,
    Cancel,
    End,
    Muted,
    Unmuted,
}

impl Kind {
    fn from_byte(byte: u8) -> Result<Self, CallError> {
        match byte {
            1 => Ok(Self::Offer),
            2 => Ok(Self::Ringing),
            3 => Ok(Self::Accept),
            4 => Ok(Self::Reject),
            5 => Ok(Self::Busy),
            6 => Ok(Self::Cancel),
            7 => Ok(Self::End),
            8 => Ok(Self::Muted),
            9 => Ok(Self::Unmuted),
            _ => Err(CallError::UnsupportedVersion),
        }
    }

    fn byte(self) -> u8 {
        match self {
            Self::Offer => 1,
            Self::Ringing => 2,
            Self::Accept => 3,
            Self::Reject => 4,
            Self::Busy => 5,
            Self::Cancel => 6,
            Self::End => 7,
            Self::Muted => 8,
            Self::Unmuted => 9,
        }
    }

    fn expected_caller(self) -> Option<bool> {
        match self {
            Self::Offer | Self::Cancel => Some(true),
            Self::Ringing | Self::Accept | Self::Reject | Self::Busy => Some(false),
            Self::End | Self::Muted | Self::Unmuted => None,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Signal {
    kind: Kind,
    call_id: [u8; 16],
    sequence: u64,
    created_unix: u64,
    expires_unix: u64,
    caller: PeerBinding,
    callee: PeerBinding,
}

impl Signal {
    fn validate(self) -> Result<(), CallError> {
        if self.call_id == [0; 16]
            || self.sequence == 0
            || self.caller == self.callee
            || self.caller.device_id.as_uuid().is_nil()
            || self.callee.device_id.as_uuid().is_nil()
            || self.caller.device_id == self.callee.device_id
            || self.caller.endpoint_id == [0; 32]
            || self.callee.endpoint_id == [0; 32]
            || self.caller.endpoint_id == self.callee.endpoint_id
        {
            return Err(CallError::InvalidIdentity);
        }
        let ttl = self.expires_unix.checked_sub(self.created_unix)
            .ok_or(CallError::InvalidLifetime)?;
        if self.created_unix == 0 || ttl == 0 || ttl > MAX_RING_TTL_SECS {
            return Err(CallError::InvalidLifetime);
        }
        Ok(())
    }

    fn encode(self) -> Wire {
        let mut frame = [0u8; WIRE_BYTES];
        frame[..8].copy_from_slice(MAGIC);
        frame[8] = VERSION;
        frame[9] = self.kind.byte();
        // frame[10] reserved: MUST remain zero (unknown required extensions fail).
        frame[OFF_CALL..OFF_SEQ].copy_from_slice(&self.call_id);
        frame[OFF_SEQ..OFF_CREATED].copy_from_slice(&self.sequence.to_be_bytes());
        frame[OFF_CREATED..OFF_EXPIRES].copy_from_slice(&self.created_unix.to_be_bytes());
        frame[OFF_EXPIRES..OFF_CALLER_DEVICE].copy_from_slice(&self.expires_unix.to_be_bytes());
        frame[OFF_CALLER_DEVICE..OFF_CALLER_ENDPOINT]
            .copy_from_slice(self.caller.device_id.as_uuid().as_bytes());
        frame[OFF_CALLER_ENDPOINT..OFF_CALLEE_DEVICE].copy_from_slice(&self.caller.endpoint_id);
        frame[OFF_CALLEE_DEVICE..OFF_CALLEE_ENDPOINT]
            .copy_from_slice(self.callee.device_id.as_uuid().as_bytes());
        frame[OFF_CALLEE_ENDPOINT..WIRE_BYTES].copy_from_slice(&self.callee.endpoint_id);
        frame
    }

    fn decode(bytes: &[u8]) -> Result<Self, CallError> {
        if bytes.len() > WIRE_BYTES {
            return Err(CallError::Oversize);
        }
        if bytes.len() != WIRE_BYTES {
            return Err(CallError::InvalidWire);
        }
        if &bytes[..8] != MAGIC || bytes[8] != VERSION || bytes[10] != 0 {
            return Err(CallError::UnsupportedVersion);
        }
        let kind = Kind::from_byte(bytes[9])?;
        let mut call_id = [0u8; 16];
        call_id.copy_from_slice(&bytes[OFF_CALL..OFF_SEQ]);
        let sequence = u64::from_be_bytes(bytes[OFF_SEQ..OFF_CREATED].try_into()
            .map_err(|_| CallError::InvalidWire)?);
        let created_unix = u64::from_be_bytes(bytes[OFF_CREATED..OFF_EXPIRES].try_into()
            .map_err(|_| CallError::InvalidWire)?);
        let expires_unix = u64::from_be_bytes(bytes[OFF_EXPIRES..OFF_CALLER_DEVICE].try_into()
            .map_err(|_| CallError::InvalidWire)?);
        let caller = PeerBinding {
            device_id: DeviceId::from_uuid(Uuid::from_bytes(
                bytes[OFF_CALLER_DEVICE..OFF_CALLER_ENDPOINT].try_into()
                    .map_err(|_| CallError::InvalidWire)?
            )),
            endpoint_id: bytes[OFF_CALLER_ENDPOINT..OFF_CALLEE_DEVICE].try_into()
                .map_err(|_| CallError::InvalidWire)?,
        };
        let callee = PeerBinding {
            device_id: DeviceId::from_uuid(Uuid::from_bytes(
                bytes[OFF_CALLEE_DEVICE..OFF_CALLEE_ENDPOINT].try_into()
                    .map_err(|_| CallError::InvalidWire)?
            )),
            endpoint_id: bytes[OFF_CALLEE_ENDPOINT..WIRE_BYTES].try_into()
                .map_err(|_| CallError::InvalidWire)?,
        };
        let signal = Self {
            kind, call_id, sequence, created_unix, expires_unix, caller, callee,
        };
        signal.validate()?;
        Ok(signal)
    }
}

fn check_peer_policy(policy: LocalPeerPolicy) -> Result<(), CallError> {
    match policy {
        LocalPeerPolicy::Allowed => Ok(()),
        LocalPeerPolicy::Revoked => Err(CallError::Revoked),
        LocalPeerPolicy::Unknown | LocalPeerPolicy::Blocked => Err(CallError::Denied),
    }
}

/// A passive single-call state machine. A host must provide OS-backed peer
/// admission, a cryptographically fresh call ID and an authenticated channel.
/// Call acceptance never opens microphones, cameras, windows or screens.
pub struct CallSession {
    offer: Signal,
    role: Role,
    phase: CallPhase,
    next_local_sequence: u64,
    next_remote_sequence: u64,
    sent_ringing: bool,
    remote_muted: bool,
}

impl CallSession {
    /// Use a fresh CSPRNG call_id; this method does NOT generate entropy.
    pub fn outbound(
        local: PeerBinding,
        remote: PeerBinding,
        call_id: [u8; 16],
        now_unix: u64,
        ttl_secs: u64,
        peer_policy: LocalPeerPolicy,
    ) -> Result<(Self, Wire), CallError> {
        check_peer_policy(peer_policy)?;
        let expires_unix = now_unix.checked_add(ttl_secs)
            .ok_or(CallError::InvalidLifetime)?;
        let offer = Signal {
            kind: Kind::Offer,
            call_id,
            sequence: 1,
            created_unix: now_unix,
            expires_unix,
            caller: local,
            callee: remote,
        };
        offer.validate()?;
        let wire = offer.encode();
        Ok((Self {
            offer,
            role: Role::Caller,
            phase: CallPhase::Dialing,
            next_local_sequence: 2,
            next_remote_sequence: 1,
            sent_ringing: false,
            remote_muted: true,
        }, wire))
    }

    /// Validate an OFFER against an *external* authenticated channel and local
    /// pinned-contact authorization. No automatic "Accept" or media capture.
    pub fn incoming(
        bytes: &[u8],
        authenticated_sender: PeerBinding,
        trusted_local: PeerBinding,
        peer_policy: LocalPeerPolicy,
        now_unix: u64,
    ) -> Result<Self, CallError> {
        check_peer_policy(peer_policy)?;
        let offer = Signal::decode(bytes)?;
        if offer.kind != Kind::Offer || offer.sequence != 1 {
            return Err(CallError::InvalidTransition);
        }
        if offer.caller != authenticated_sender || offer.callee != trusted_local {
            return Err(CallError::WrongPeer);
        }
        if now_unix < offer.created_unix {
            return Err(CallError::NotYetValid);
        }
        if now_unix >= offer.expires_unix {
            return Err(CallError::Expired);
        }
        Ok(Self {
            offer,
            role: Role::Callee,
            phase: CallPhase::IncomingRinging,
            next_local_sequence: 1,
            next_remote_sequence: 2,
            sent_ringing: false,
            remote_muted: true,
        })
    }

    pub fn phase(&self) -> CallPhase {
        self.phase
    }

    /// Informative only; "RemoteMuted(false)" is NEVER media permission.
    pub fn remote_muted(&self) -> bool {
        self.remote_muted
    }

    pub fn ring_local(&mut self, now_unix: u64) -> Result<Wire, CallError> {
        if self.role != Role::Callee || self.phase != CallPhase::IncomingRinging
            || self.sent_ringing
        {
            return Err(CallError::InvalidTransition);
        }
        self.not_expired(now_unix)?;
        let wire = self.emit(Kind::Ringing)?;
        self.sent_ringing = true;
        Ok(wire)
    }

    /// Revalidate the authenticated remote key and current host decision
    /// before a local Accept; no sequence number is consumed.
    pub fn verify_local_accept_peer(
        &mut self,
        authenticated_remote: PeerBinding,
        policy: LocalPeerPolicy,
    ) -> Result<(), CallError> {
        if self.role != Role::Callee || self.phase != CallPhase::IncomingRinging {
            return Err(CallError::InvalidTransition);
        }
        if let Err(error) = check_peer_policy(policy) {
            self.revoke();
            return Err(error);
        }
        if self.offer.caller != authenticated_remote {
            self.revoke();
            return Err(CallError::WrongPeer);
        }
        Ok(())
    }

    /// Approval of the CALL only. Device capture consent is a separate OS flow.
    pub fn accept_local(&mut self, now_unix: u64) -> Result<Wire, CallError> {
        if self.role != Role::Callee || self.phase != CallPhase::IncomingRinging
            || !self.sent_ringing
        {
            return Err(CallError::InvalidTransition);
        }
        self.not_expired(now_unix)?;
        let wire = self.emit(Kind::Accept)?;
        self.phase = CallPhase::Active;
        Ok(wire)
    }

    pub fn refuse_local(&mut self, refusal: Refusal, now_unix: u64)
        -> Result<Wire, CallError>
    {
        if self.role != Role::Callee || self.phase != CallPhase::IncomingRinging {
            return Err(CallError::InvalidTransition);
        }
        self.not_expired(now_unix)?;
        let kind = match refusal { Refusal::Reject => Kind::Reject, Refusal::Busy => Kind::Busy };
        let wire = self.emit(kind)?;
        self.phase = CallPhase::Closed;
        Ok(wire)
    }

    fn emit(&mut self, kind: Kind) -> Result<Wire, CallError> {
        if self.next_local_sequence == u64::MAX {
            return Err(CallError::SequenceExhausted);
        }
        let sequence = self.next_local_sequence;
        let wire = Signal {kind, sequence, ..self.offer}.encode();
        self.next_local_sequence += 1;
        Ok(wire)
    }

    fn not_expired(&mut self, now_unix: u64) -> Result<(), CallError> {
        if now_unix < self.offer.created_unix {
            return Err(CallError::NotYetValid);
        }
        if now_unix >= self.offer.expires_unix {
            self.phase = CallPhase::Closed;
            return Err(CallError::Expired);
        }
        Ok(())
    }

    /// Only receives remote control events, validated against the external
    /// QUIC peer and independently updated local allow/revoke decision.
    /// No incoming event is allowed to activate any capture device.
    pub fn receive(
        &mut self,
        bytes: &[u8],
        authenticated_remote: PeerBinding,
        peer_policy: LocalPeerPolicy,
        now_unix: u64,
    ) -> Result<RemoteEvent, CallError> {
        if self.phase == CallPhase::Closed {
            return Err(CallError::Closed);
        }
        if let Err(error) = check_peer_policy(peer_policy) {
            // A revoked/blocked peer ends an existing call immediately.
            self.phase = CallPhase::Closed;
            return Err(error);
        }
        let remote = match self.role {
            Role::Caller => self.offer.callee,
            Role::Callee => self.offer.caller,
        };
        if authenticated_remote != remote {
            return Err(CallError::WrongPeer);
        }
        let message = Signal::decode(bytes)?;
        if message.call_id != self.offer.call_id
            || message.caller != self.offer.caller
            || message.callee != self.offer.callee
            || message.created_unix != self.offer.created_unix
            || message.expires_unix != self.offer.expires_unix
        {
            return Err(CallError::WrongCall);
        }
        let remote_is_caller = self.role == Role::Callee;
        if message.kind.expected_caller().is_some_and(|expected| expected != remote_is_caller) {
            return Err(CallError::InvalidTransition);
        }
        if message.sequence < self.next_remote_sequence {
            return Err(CallError::Replay);
        }
        if message.sequence > self.next_remote_sequence {
            return Err(CallError::OutOfOrder);
        }
        if self.phase != CallPhase::Active {
            self.not_expired(now_unix)?;
        }
        let (event, next_phase) = match (self.role, self.phase, message.kind) {
            (Role::Caller, CallPhase::Dialing, Kind::Ringing) =>
                (RemoteEvent::Ringing, CallPhase::RemoteRinging),
            (Role::Caller, CallPhase::RemoteRinging, Kind::Accept) =>
                (RemoteEvent::Accepted, CallPhase::Active),
            (Role::Caller, CallPhase::Dialing | CallPhase::RemoteRinging, Kind::Reject) =>
                (RemoteEvent::Rejected, CallPhase::Closed),
            (Role::Caller, CallPhase::Dialing | CallPhase::RemoteRinging, Kind::Busy) =>
                (RemoteEvent::Busy, CallPhase::Closed),
            (Role::Callee, CallPhase::IncomingRinging, Kind::Cancel) =>
                (RemoteEvent::Cancelled, CallPhase::Closed),
            (_, CallPhase::Active, Kind::End) =>
                (RemoteEvent::Ended, CallPhase::Closed),
            (_, CallPhase::Active, Kind::Muted) =>
                (RemoteEvent::RemoteMuted(true), CallPhase::Active),
            (_, CallPhase::Active, Kind::Unmuted) =>
                (RemoteEvent::RemoteMuted(false), CallPhase::Active),
            _ => return Err(CallError::InvalidTransition),
        };
        if self.next_remote_sequence == u64::MAX {
            return Err(CallError::SequenceExhausted);
        }
        self.next_remote_sequence += 1;
        self.phase = next_phase;
        if let RemoteEvent::RemoteMuted(value) = event {
            self.remote_muted = value;
        }
        Ok(event)
    }

    /// A second close is a harmless no-op, not a second network packet.
    pub fn end_local(&mut self) -> Result<Option<Wire>, CallError> {
        if self.phase == CallPhase::Closed {
            return Ok(None);
        }
        let kind = match (self.role, self.phase) {
            (Role::Caller, CallPhase::Dialing | CallPhase::RemoteRinging) => Kind::Cancel,
            (Role::Callee, CallPhase::IncomingRinging) => Kind::Reject,
            (_, CallPhase::Active) => Kind::End,
            _ => return Err(CallError::InvalidTransition),
        };
        let wire = self.emit(kind)?;
        self.phase = CallPhase::Closed;
        Ok(Some(wire))
    }

    /// Remote mute state is display-only; it cannot start local audio devices.
    pub fn notify_local_muted(&mut self, muted: bool) -> Result<Wire, CallError> {
        if self.phase != CallPhase::Active {
            return Err(CallError::InvalidTransition);
        }
        self.emit(if muted {Kind::Muted} else {Kind::Unmuted})
    }

    pub fn expire(&mut self, now_unix: u64) -> bool {
        if self.phase != CallPhase::Closed && self.phase != CallPhase::Active
            && now_unix >= self.offer.expires_unix
        {
            self.phase = CallPhase::Closed;
            return true;
        }
        false
    }

    /// Losing the independently authenticated network channel ends this call.
    /// A new QUIC path or connection cannot implicitly restore its permission.
    /// The host MUST also stop any OS media capture and obtain fresh call and
    /// device consent on a new session with a fresh CSPRNG call ID.
    pub fn transport_lost(&mut self) {
        self.phase = CallPhase::Closed;
        self.remote_muted = true;
    }

    pub fn revoke(&mut self) {
        self.phase = CallPhase::Closed;
        self.remote_muted = true;
    }
}

